  items,
  onDelete,
  onRetry,
}: Props): ReactElement => (
  <StyledUploadedFileChips data-testid="stFileChips">
    <StyledUploadedFileChipList>
      {items.map(file => (
        <StyledUploadedFileChipListItem key={file.id}>
          <UploadedFileChip
            fileInfo={file}
            onDelete={onDelete}
            onRetry={onRetry}
          />
        </StyledUploadedFileChipListItem>
      ))}
    </StyledUploadedFileChipList>
  </StyledUploadedFileChips>
)

export default memo(UploadedFileChips)
